package org.firstinspires.ftc.teamcode.subsystems;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;

// Generated by refract-suite ftc-construct. The shot table (saved points: distance, speed, hood, feed) as a curve, no
// hardware in here. A saved point is the first setting that went 4 for 4 at that spot, so it sits somewhere inside the
// "it scores" window, not in its middle. Averaging neighbouring points (a local quadratic fitted to the K nearest,
// nearer ones weighing more) estimates the middle; straight lines between the points copy each point's luck.
// Per column the method is picked from the points themselves: every inner point is left out in turn and predicted from
// the others; the method that predicts them best is used (straight lines when that is best, and always below
// MIN_POINTS). Guards: the curve stays within NODE_STEPS tuning steps of every saved point (a point it had to be
// pulled back to is named), within OVERSHOOT_STEPS of the two points around it, and the speed never drops as the
// distance grows when the points do not. Past the first / last point the curve's end value is held (the sim scored
// that best); the Launcher clamps (hood range, 95 % of top speed).
public final class ShotCurve {
    public static final int DISTANCE = 0, SPEED = 1, HOOD = 2, FEED = 3, LINES = 0;
    // one button press in programs 8 / 9 per column (speed ticks/s, hood, feed): the guards count in these
    static final double[] STEP = {0, 20, 0.005, 0.05};
    static final int[] NEIGHBOURS = {4, 5, 6, 8, 10, 12};
    public static final int MIN_POINTS = 5;
    static final double NODE_STEPS = 2, OVERSHOOT_STEPS = 2, WIDEN = 1.5;

    private final double[][] rows;
    private final boolean smooth;
    private final int[] method = new int[4];
    private final double[] typicalMiss = new double[4];
    private final double[][] excess = new double[4][];
    private final List<String> pulled = new ArrayList<>();

    // table rows {distance, speed, hood, feed}; smooth = false: straight lines only (the old way)
    public ShotCurve(double[][] table, boolean smooth) {
        this.smooth = smooth;
        rows = table.clone();
        Arrays.sort(rows, (a, b) -> Double.compare(a[DISTANCE], b[DISTANCE]));
        for (int col = SPEED; col <= FEED; col++) {
            excess[col] = new double[rows.length];
            method[col] = LINES;
            if (!smooth || rows.length < MIN_POINTS) continue;
            double best = typicalMiss(col, LINES);
            typicalMiss[col] = best;
            for (int k : NEIGHBOURS) {
                if (k > rows.length - 1) break;
                double miss = typicalMiss(col, k);
                if (miss < best - 1e-9) {
                    best = miss;
                    method[col] = k;
                    typicalMiss[col] = miss;
                }
            }
            if (method[col] == LINES) continue;
            double limit = NODE_STEPS * STEP[col];
            for (int i = 0; i < rows.length; i++) {
                double r = fit(rows, col, rows[i][DISTANCE], method[col]) - rows[i][col];
                excess[col][i] = r - Math.max(-limit, Math.min(limit, r));
                if (excess[col][i] != 0) {
                    pulled.add(String.format(Locale.US, "%s at %.0f in", col == SPEED ? "speed" : col == HOOD ? "hood" : "feed", rows[i][DISTANCE]));
                }
            }
            if (col == SPEED && rises(rows, SPEED) && !rises(col)) {
                method[col] = LINES;
                Arrays.fill(excess[col], 0);
                pulled.removeIf(p -> p.startsWith("speed"));
            }
        }
    }

    public double speed(double d) {
        return value(SPEED, d);
    }

    public double hood(double d) {
        return value(HOOD, d);
    }

    public double feed(double d) {
        return value(FEED, d);
    }

    public int points() {
        return rows.length;
    }

    // LINES or the number of neighbours averaged
    public int method(int col) {
        return method[col];
    }

    // points the curve could not follow within NODE_STEPS: probably a lucky / unlucky point, worth redoing
    public List<String> pulled() {
        return pulled;
    }

    // e.g. "speed: 5 points averaged (typical miss 12), hood: straight lines"
    public String describe() {
        StringBuilder b = new StringBuilder();
        for (int col = SPEED; col <= FEED; col++) {
            if (b.length() > 0) b.append(", ");
            b.append(col == SPEED ? "speed: " : col == HOOD ? "hood: " : "feed: ");
            b.append(method[col] == LINES ? "straight lines" : String.format(Locale.US, "%d points averaged (typical miss %s)",
                    method[col], col == SPEED ? String.format(Locale.US, "%.0f", typicalMiss[col]) : String.format(Locale.US, "%.3f", typicalMiss[col])));
        }
        return b.toString();
    }

    public double value(int col, double d) {
        int n = rows.length;
        if (n == 0 || Double.isNaN(d)) return Double.NaN;
        if (n == 1) return rows[0][col];
        double first = rows[0][DISTANCE], last = rows[n - 1][DISTANCE];
        boolean outside = d < first || d > last;
        if (!smooth || method[col] == LINES) return lines(rows, col, d);
        // past the ends: the curve's end value. Carrying the fit on (DECODE's way) scored worst in the sim (15.2 of 20
        // launchers' make chance past the end, against 17.4 holding the last point and 18.3 holding the curve's end)
        if (outside) return value(col, d > last ? last : first);
        double v = fit(rows, col, d, method[col]) - interpolate(excess[col], d);
        int j = 1;
        while (rows[j][DISTANCE] < d) j++;
        double lo = Math.min(rows[j - 1][col], rows[j][col]) - OVERSHOOT_STEPS * STEP[col];
        double hi = Math.max(rows[j - 1][col], rows[j][col]) + OVERSHOOT_STEPS * STEP[col];
        return Math.max(lo, Math.min(hi, v));
    }

    // ---------- the pieces ----------

    // straight lines between the points, the ends held (the old Launcher.lookup)
    static double lines(double[][] rows, int col, double d) {
        double dd = Math.max(rows[0][DISTANCE], Math.min(rows[rows.length - 1][DISTANCE], d));
        for (int k = 1; k < rows.length; k++) {
            if (dd <= rows[k][DISTANCE]) {
                double[] a = rows[k - 1], b = rows[k];
                double span = b[DISTANCE] - a[DISTANCE];
                double t = span > 0 ? (dd - a[DISTANCE]) / span : 0;
                return a[col] + t * (b[col] - a[col]);
            }
        }
        return rows[rows.length - 1][col];
    }

    // a quadratic fitted to the k points nearest d (tricube weights, the furthest of them still counting), value at d
    static double fit(double[][] rows, int col, double d, int k) {
        Integer[] order = new Integer[rows.length];
        for (int i = 0; i < order.length; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Double.compare(Math.abs(rows[a][DISTANCE] - d), Math.abs(rows[b][DISTANCE] - d)));
        int m = Math.min(k, rows.length);
        double h = 0;
        for (int i = 0; i < m; i++) h = Math.max(h, Math.abs(rows[order[i]][DISTANCE] - d));
        h *= WIDEN;
        double[] x = new double[m], y = new double[m], w = new double[m];
        for (int i = 0; i < m; i++) {
            double[] r = rows[order[i]];
            x[i] = r[DISTANCE] - d;
            y[i] = r[col];
            double u = h > 0 ? Math.abs(x[i]) / h : 0;
            w[i] = Math.pow(1 - u * u * u, 3);
        }
        // centred on d, so the constant term is the value at d; fall back to a line, then to the weighted mean
        for (int degree = 2; degree >= 0; degree--) {
            double[] c = weightedFit(x, y, w, degree);
            if (c != null) return c[0];
        }
        return Double.NaN;
    }

    private static double[] weightedFit(double[] x, double[] y, double[] w, int degree) {
        int p = degree + 1;
        double[][] a = new double[p][p + 1];
        for (int i = 0; i < x.length; i++) {
            double[] pow = new double[2 * p];
            pow[0] = 1;
            for (int j = 1; j < 2 * p; j++) pow[j] = pow[j - 1] * x[i];
            for (int r = 0; r < p; r++) {
                for (int c = 0; c < p; c++) a[r][c] += w[i] * pow[r + c];
                a[r][p] += w[i] * pow[r] * y[i];
            }
        }
        // Gauss-Jordan with partial pivoting; a (near) singular system = not enough distinct distances for this degree
        double scale = 0;
        for (double[] row : a) for (int c = 0; c < p; c++) scale = Math.max(scale, Math.abs(row[c]));
        for (int col = 0; col < p; col++) {
            int piv = col;
            for (int r = col + 1; r < p; r++) if (Math.abs(a[r][col]) > Math.abs(a[piv][col])) piv = r;
            if (Math.abs(a[piv][col]) <= 1e-9 * Math.max(scale, 1e-12)) return null;
            double[] t = a[col];
            a[col] = a[piv];
            a[piv] = t;
            for (int r = 0; r < p; r++) {
                if (r == col) continue;
                double f = a[r][col] / a[col][col];
                for (int c = col; c <= p; c++) a[r][c] -= f * a[col][c];
            }
        }
        double[] out = new double[p];
        for (int i = 0; i < p; i++) out[i] = a[i][p] / a[i][i];
        return out;
    }

    // the typical miss (mean absolute) of a method predicting each inner point from all the others
    private double typicalMiss(int col, int method) {
        double sum = 0;
        int count = 0;
        for (int i = 1; i < rows.length - 1; i++) {
            double[][] others = new double[rows.length - 1][];
            for (int j = 0, o = 0; j < rows.length; j++) if (j != i) others[o++] = rows[j];
            double d = rows[i][DISTANCE];
            double p = method == LINES ? lines(others, col, d) : fit(others, col, d, method);
            sum += Math.abs(p - rows[i][col]);
            count++;
        }
        return count == 0 ? Double.POSITIVE_INFINITY : sum / count;
    }

    // per-point values (the excess) joined by straight lines over the points' distances, the ends held
    private double interpolate(double[] at, double d) {
        int n = rows.length;
        if (d <= rows[0][DISTANCE]) return at[0];
        if (d >= rows[n - 1][DISTANCE]) return at[n - 1];
        int k = 1;
        while (rows[k][DISTANCE] < d) k++;
        double span = rows[k][DISTANCE] - rows[k - 1][DISTANCE];
        double t = span > 0 ? (d - rows[k - 1][DISTANCE]) / span : 0;
        return at[k - 1] + t * (at[k] - at[k - 1]);
    }

    private static boolean rises(double[][] rows, int col) {
        for (int i = 1; i < rows.length; i++) if (rows[i][col] < rows[i - 1][col]) return false;
        return true;
    }

    // the fitted column never drops by more than half a step as the distance grows (checked every half inch)
    private boolean rises(int col) {
        double first = rows[0][DISTANCE], last = rows[rows.length - 1][DISTANCE];
        double prev = value(col, first);
        for (double d = first + 0.5; d <= last + 1e-9; d += 0.5) {
            double v = value(col, d);
            if (v < prev - STEP[col] / 2) return false;
            prev = v;
        }
        return true;
    }
}
